(() => {
  const menuBtn = document.getElementById('menuBtn');
  const mainNav = document.getElementById('mainNav');
  if (menuBtn && mainNav) {
    menuBtn.addEventListener('click', () => mainNav.classList.toggle('open'));
    mainNav.querySelectorAll('a').forEach(a => a.addEventListener('click', () => mainNav.classList.remove('open')));
  }

  const backTop = document.getElementById('backTop');
  window.addEventListener('scroll', () => {
    if (backTop) backTop.classList.toggle('show', window.scrollY > 650);
  });
  backTop?.addEventListener('click', () => window.scrollTo({ top: 0, behavior: 'smooth' }));

  const pageData = {"1":{"title":"Executive Overview","subtitle":"Executive summary, marketplace health, analytical scope and the management questions that frame the report.","html":"<div class=\"page-story-head\">\n   <div><span class=\"story-kicker\">EXECUTIVE SUMMARY</span><h2>Marketplace scale is meaningful, but growth quality depends on what happens after seller acquisition.</h2></div>\n   <p>This opening page is written for management: it separates marketplace scale from growth quality, identifies the three risks that deserve attention, and defines the measurement boundary before any action is recommended.</p>\n </div>\n <div class=\"story-metrics five\">\n   <div><strong>R$13.59M</strong><span>GMV proxy</span></div><div><strong>98,666</strong><span>Orders</span></div><div><strong>3,095</strong><span>Sellers</span></div><div><strong>15.8%</strong><span>30D activation</span></div><div><strong>82.7%</strong><span>Top-20% seller share</span></div>\n </div>\n <div class=\"analysis-lens-grid\">\n   <section class=\"analysis-lens\"><span>KEY FINDINGS</span><h3>Breadth improved in the last complete month, but value depth weakened.</h3><p>From Jul→Aug 2018, orders increased 2.9% and active sellers 1.3%, while GMV fell 4.6%, AOV fell 7.2%, and GMV per active seller fell 5.8%.</p></section>\n   <section class=\"analysis-lens\"><span>BUSINESS INTERPRETATION</span><h3>More activity does not automatically mean healthier growth.</h3><p>Marketplace breadth and seller productivity are moving differently. Management should avoid using order count or seller count as a standalone health signal.</p></section>\n   <section class=\"analysis-lens decision\"><span>RECOMMENDED ACTION</span><h3>Manage growth quality, not just top-line volume.</h3><p>Track volume, value per transaction, seller productivity, activation speed and customer experience as one operating system.</p></section>\n </div>\n <div class=\"story-grid two\">\n   <section class=\"story-card\"><span class=\"card-label\">LATEST COMPLETE PERIOD</span><h3>Jul 2018 → Aug 2018</h3>\n     <div class=\"story-table-wrap\"><table class=\"story-table\"><thead><tr><th>Metric</th><th>Jul</th><th>Aug</th><th>Change</th><th>Management read</th></tr></thead><tbody>\n       <tr><td>GMV Proxy</td><td>R$895.5K</td><td>R$854.7K</td><td class=\"neg\">−4.6%</td><td>Value softened</td></tr>\n       <tr><td>Orders</td><td>6,273</td><td>6,452</td><td class=\"pos\">+2.9%</td><td>Volume expanded</td></tr>\n       <tr><td>Active Sellers</td><td>1,261</td><td>1,278</td><td class=\"pos\">+1.3%</td><td>Seller breadth expanded</td></tr>\n       <tr><td>AOV</td><td>R$142.76</td><td>R$132.47</td><td class=\"neg\">−7.2%</td><td>Order value weakened</td></tr>\n       <tr><td>GMV / Seller</td><td>R$710.16</td><td>R$668.77</td><td class=\"neg\">−5.8%</td><td>Seller productivity weakened</td></tr>\n     </tbody></table></div>\n   </section>\n   <section class=\"story-card visual-card\"><span class=\"card-label\">MEASUREMENT RISK</span><h3>A naïve join would overstate GMV by 4.54%</h3><img loading=\"lazy\" src=\"https://raw.githubusercontent.com/susayold/marketplace-growth-seller-intelligence/main/reports/charts/00_measurement_trust/trust_02_grain_safe_vs_naive_gmv.png\" alt=\"Grain safe versus naive GMV\"><p class=\"card-foot\">Grain-safe GMV = R$13.5916M vs naïve joined GMV = R$14.2091M, a ~R$617.5K gap.</p></section>\n </div>\n <div class=\"senior-assessment\">\n  <div class=\"assessment-title\"><span>DETAILED ANALYSIS</span><h3>Marketplace performance: growth breadth versus value depth</h3></div>\n  <div class=\"assessment-copy\">\n    <p><b>The data indicates that the marketplace is not simply “growing” or “declining”.</b> The final complete-month comparison shows two different stories happening at the same time. Transaction breadth improved: orders increased 2.9% and active sellers increased 1.3%. But value depth weakened: GMV fell 4.6%, AOV fell 7.2%, and GMV per active seller fell 5.8%. This means more activity is flowing through the marketplace, but each transaction and each active seller is generating less value than in the prior complete month.</p>\n    <p>From a management perspective, that changes the question from “Are we growing?” to <b>“What type of growth are we creating?”</b> If the team only watches order count, the picture looks positive. If it only watches GMV, the picture looks negative. The correct interpretation is that breadth expanded while monetization/productivity softened. That is exactly why executive reporting should separate volume, AOV, seller productivity and customer-experience health rather than compressing everything into one headline KPI.</p>\n    <p>Measurement integrity is the second critical point. A naïve payment × order-item join inflates GMV by 4.54%, roughly R$617.5K. At executive level, that is not a minor technical detail; it is large enough to change how performance is interpreted. The project therefore treats grain-safe metric construction as part of the business decision process, not as back-office data cleaning.</p>\n  </div>\n  <div class=\"assessment-decision\"><b>Management implication</b><p>Use this page as the weekly health check: first confirm the reporting period is valid, then read volume, value and productivity together. If orders rise while AOV and GMV/seller fall again, the next diagnostic should move into category mix, seller mix and acquisition/activation quality rather than celebrating volume growth.</p></div>\n</div><div class=\"management-box\"><div><span>EXECUTIVE IMPLICATION</span><h3>The first management decision is to trust the metric before reacting to the trend.</h3></div><p>Raw order observations continue beyond Aug 2018, but executive-complete reporting ends on <b>31 Aug 2018</b>. Partial Sep/Oct tail periods are excluded from performance conclusions so that a source-cutoff problem is not mistaken for a commercial collapse.</p></div>\n "},"2":{"title":"Seller Acquisition","subtitle":"Marketing funnel scale, channel conversion, seller value and the decision framework for acquisition quality.","html":"<div class=\"page-story-head\">\n   <div><span class=\"story-kicker\">MARKETING & SELLER ACQUISITION</span><h2>Acquisition is generating seller volume, but the right question is which sources create productive sellers — not which source has the highest conversion alone.</h2></div>\n   <p>This page evaluates seller-acquisition quality from lead generation through observed conversion and downstream value. It deliberately separates marketing efficiency from seller quality.</p>\n </div>\n <div class=\"story-metrics four\"><div><strong>8,000</strong><span>Marketing Qualified Leads</span></div><div><strong>842</strong><span>Closed / converted sellers</span></div><div><strong>10.5%</strong><span>Observed conversion</span></div><div><strong>0.131</strong><span>Cramér’s V</span></div></div>\n <div class=\"analysis-lens-grid\">\n   <section class=\"analysis-lens\"><span>KEY FINDINGS</span><h3>Paid Search and Organic Search combine scale with above-average conversion.</h3><p>Paid Search converts at 12.3% and Organic Search at 11.8%, while Social converts at 5.6% despite meaningful lead volume.</p></section>\n   <section class=\"analysis-lens\"><span>BUSINESS INTERPRETATION</span><h3>Origin matters, but its effect is modest and conversion is only one funnel stage.</h3><p>The global association is statistically detectable, yet Cramér’s V of 0.131 is modest. Lead intent, seller readiness and channel mix can still explain part of the observed difference.</p></section>\n   <section class=\"analysis-lens decision\"><span>RECOMMENDED ACTION</span><h3>Replace the single conversion-rate view with a multi-stage scorecard.</h3><p>Use MQL volume → conversion → downstream GMV / matched seller → activation → M3 retention guardrail.</p></section>\n </div>\n <div class=\"story-grid two\">\n   <section class=\"story-card\"><span class=\"card-label\">CHANNEL PERFORMANCE</span><h3>Observed conversion and downstream value</h3>\n     <div class=\"story-table-wrap\"><table class=\"story-table\"><thead><tr><th>Origin</th><th>MQLs</th><th>Converted</th><th>Conversion</th><th>GMV / matched seller</th></tr></thead><tbody>\n       <tr><td>Organic Search</td><td>2,296</td><td>271</td><td>11.8%</td><td>R$763.92</td></tr>\n       <tr><td>Paid Search</td><td>1,586</td><td>195</td><td>12.3%</td><td>R$796.29</td></tr>\n       <tr><td>Social</td><td>1,350</td><td>75</td><td>5.6%</td><td>R$579.71</td></tr>\n       <tr><td>Direct Traffic</td><td>499</td><td>56</td><td>11.2%</td><td>R$391.14</td></tr>\n       <tr><td>Referral</td><td>284</td><td>24</td><td>8.5%</td><td>R$745.30</td></tr>\n       <tr><td>Email</td><td>493</td><td>15</td><td>3.0%</td><td>R$565.67</td></tr>\n       <tr class=\"muted-row\"><td>Unknown</td><td>1,159</td><td>193</td><td>16.7%</td><td>R$1,113.91</td></tr>\n     </tbody></table></div>\n     <p class=\"card-foot\"><b>Unknown</b> remains in the denominator for data integrity, but it is not an actionable acquisition channel and should not be presented as the “winner.”</p>\n   </section>\n   <section class=\"story-card visual-card\"><span class=\"card-label\">CHANNEL QUALITY BEYOND CONVERSION</span><h3>Conversion and seller value are different dimensions</h3><img loading=\"lazy\" src=\"https://raw.githubusercontent.com/susayold/marketplace-growth-seller-intelligence/main/reports/charts/02_acquisition/acq_04_conversion_vs_downstream_value.png\" alt=\"Conversion versus downstream seller value\"><p class=\"card-foot\">χ² = 137.69, df = 9, p ≈ 3.1×10⁻²⁵. The association exists, but effect size is modest and not causal.</p></section>\n </div>\n <div class=\"report-subsection\"><div class=\"subsection-head\"><span>CHANNEL ASSESSMENT</span><h3>A high-converting source is not automatically a high-quality source.</h3></div>\n   <div class=\"quadrant-grid\"><div><b>High conversion + High value</b><span>Scale candidate</span></div><div><b>High conversion + Low value</b><span>Quality diagnostic</span></div><div><b>Low conversion + High value</b><span>Funnel optimization opportunity</span></div><div><b>Low conversion + Low value</b><span>Lower-priority / reassess</span></div></div>\n </div>\n <div class=\"senior-assessment\">\n  <div class=\"assessment-title\"><span>DETAILED ANALYSIS</span><h3>Acquisition channel performance and seller quality</h3></div>\n  <div class=\"assessment-copy\">\n    <p><b>Paid Search and Organic Search are the strongest large actionable origins on observed conversion, while Social produces meaningful lead volume but materially weaker conversion.</b> Paid Search converts at 12.3%, Organic Search at 11.8%, and Social at 5.6%. That immediately tells management that lead volume alone is not enough: a large top-of-funnel source can still be inefficient at moving sellers into the closed stage.</p>\n    <p>Conversion alone is not sufficient. Direct Traffic is a good example of why. Its observed conversion is 11.2%, close to Paid Search and Organic Search, yet downstream GMV per matched seller is much lower. So two channels can look similar at the lead-to-close stage and still create very different economic outcomes after conversion. This is the key reason the acquisition team should stop ranking sources with one percentage.</p>\n    <p>The statistical result supports this direction without making it the whole story. Origin and conversion are associated, but the effect size is modest. In practical terms, channel matters, but it is not the only thing determining seller success. Lead intent, seller readiness, category mix and seller capability are likely contributing to the observed differences. For management, the implication is to treat channel as a segmentation variable and an experiment target, not as a deterministic quality label.</p>\n    <p>The size of the unattributed “Unknown” group also requires attention. It converts strongly in the historical data, but because it is not an actionable channel label, it should trigger an attribution-quality workstream rather than a budget recommendation. A channel mix cannot be governed confidently if a meaningful share of sellers cannot be traced back to a usable acquisition origin.</p>\n  </div>\n  <div class=\"assessment-decision\"><b>Management implication</b><p>Build one weekly acquisition scorecard with five linked stages: <b>MQL volume → conversion → downstream GMV per matched seller → 30D activation → M3 retention guardrail</b>. Scale a source only when performance survives across the chain, not because one funnel rate looks attractive.</p></div>\n</div><div class=\"management-box\"><div><span>RECOMMENDATION</span><h3>Test channels; do not reallocate budget from historical conversion alone.</h3></div><p>Current data does not contain marketing spend, CAC or ROAS, and origin-specific M3 retention remains imprecise. The evidence is sufficient to prioritize experiments, but not to claim a definitive “best” channel for investment.</p></div>\n "},"3":{"title":"Seller Activation & Retention","subtitle":"Post-conversion leakage, time-to-first-sale, activation windows and retention as a quality guardrail.","html":"<div class=\"page-story-head\">\n   <div><span class=\"story-kicker\">POST-CONVERSION QUALITY</span><h2>The largest seller-growth bottleneck appears after conversion: sellers are taking too long to become economically active.</h2></div>\n   <p>Closing a seller creates potential supply. Activation determines when that potential becomes real marketplace supply. This page measures time-to-first-sale using observable windows and keeps right-censoring explicit.</p>\n </div>\n <div class=\"story-flow\"><div><strong>842</strong><span>Closed sellers</span></div><i>→</i><div><strong>840</strong><span>Activation eligible</span></div><i>→</i><div><strong>380</strong><span>Observed activated</span></div><i>+</i><div><strong>460</strong><span>Right-censored</span></div></div>\n <div class=\"story-metrics four\"><div><strong>15.8%</strong><span>30D · 130 / 825</span></div><div><strong>30.8%</strong><span>60D · 247 / 803</span></div><div><strong>42.1%</strong><span>90D · 324 / 769</span></div><div><strong>44.3 days</strong><span>Observed activator median</span></div></div>\n <div class=\"analysis-lens-grid\">\n   <section class=\"analysis-lens\"><span>KEY FINDINGS</span><h3>Most closed sellers are not producing a first sale quickly.</h3><p>Only 15.8% of sellers with a full 30-day observation window activate within 30 days. Even by 90 days, cumulative observed activation is 42.1%.</p></section>\n   <section class=\"analysis-lens\"><span>BUSINESS INTERPRETATION</span><h3>Marketing creates potential supply; onboarding determines time-to-value.</h3><p>The funnel is leaking after conversion. Growth cannot be managed purely as a lead-generation problem when many converted sellers remain economically inactive for long periods.</p></section>\n   <section class=\"analysis-lens decision\"><span>RECOMMENDED ACTION</span><h3>Manage onboarding as a measurable journey.</h3><p>Instrument Day 7, Day 30 and Day 60 checkpoints, then test interventions against activation while retaining M3 retention and downstream GMV as guardrails.</p></section>\n </div>\n <div class=\"story-grid two\">\n   <section class=\"story-card visual-card\"><span class=\"card-label\">ACTIVATION CURVE</span><h3>Fixed-window activation with observable denominators</h3><img loading=\"lazy\" src=\"https://raw.githubusercontent.com/susayold/marketplace-growth-seller-intelligence/main/reports/charts/03_activation/act_05_30_60_90_activation_ci.png\" alt=\"Activation rates with confidence intervals\"><p class=\"card-foot\">Sellers without enough follow-up time are not mislabeled as failures. This is the canonical v3 activation definition.</p></section>\n   <section class=\"story-card visual-card\"><span class=\"card-label\">RETENTION GUARDRAIL</span><h3>Earlier activation aligns with stronger observed M3 retention</h3><img loading=\"lazy\" src=\"https://raw.githubusercontent.com/susayold/marketplace-growth-seller-intelligence/main/reports/charts/04_retention/ret_05_retention_by_activation_speed.png\" alt=\"Retention by activation speed\"><p class=\"card-foot\">Observed M3 retention is 62.7% for 8–30d activators versus 22.7% for &gt;90d activators. This relationship is associative, not causal.</p></section>\n </div>\n <div class=\"report-subsection\"><div class=\"subsection-head\"><span>OPERATING SEGMENTATION</span><h3>Use activation speed as an early-warning segmentation variable.</h3></div>\n   <div class=\"status-bands\"><div class=\"green\"><strong>≤30 days</strong><span>Healthy / monitor</span></div><div class=\"amber\"><strong>31–60 days</strong><span>Onboarding support</span></div><div class=\"red\"><strong>&gt;60 days</strong><span>Escalate diagnostic</span></div></div>\n </div>\n <div class=\"senior-assessment\">\n  <div class=\"assessment-title\"><span>DETAILED ANALYSIS</span><h3>Seller activation and time-to-value</h3></div>\n  <div class=\"assessment-copy\">\n    <p><b>The activation page is where the project moves from marketing efficiency to marketplace economics.</b> Acquisition can close a seller, but the seller does not create economic supply until the first sale occurs. Only 15.8% of sellers observable for a full 30-day window activate within 30 days. By 60 days the rate reaches 30.8%, and by 90 days 42.1%. That curve tells management that many sellers eventually activate, but value realization is delayed.</p>\n    <p>The 44.3-day observed activator median reinforces the same business message: seller time-to-value is slow. This matters because a marketplace can keep spending effort on lead generation and sales while a large share of already-acquired sellers are still waiting to become productive. Operationally, that means the next unit of growth may come more efficiently from improving post-close onboarding than from simply adding more MQLs.</p>\n    <p>The retention view makes activation even more useful as an operating signal. Sellers who activate earlier show stronger observed M3 retention than sellers who take much longer. This does not prove that faster activation itself creates retention; it should be used as a segmentation rule. Slow activation identifies a seller cohort that deserves earlier intervention because it is also associated with weaker downstream outcomes.</p>\n    <p>That is why the report should not label unactivated sellers as “failed”. The useful management question is: <b>which sellers are still not creating value at Day 7, Day 30 and Day 60, and what intervention should happen at each checkpoint?</b></p>\n  </div>\n  <div class=\"assessment-decision\"><b>Management implication</b><p>Treat onboarding as a managed funnel. Day 7 checks readiness/setup, Day 30 becomes the primary activation KPI, and Day 60 becomes an escalation point. Any onboarding intervention should be evaluated against both activation lift and downstream seller value/retention so the team does not optimize speed at the expense of seller quality.</p></div>\n</div><div class=\"management-box\"><div><span>RECOMMENDATION</span><h3>Prioritize seller time-to-value before adding more top-of-funnel volume.</h3></div><p>An onboarding change should be scaled only when activation improves <b>without deterioration in M3 retention or downstream seller value</b>. Faster first sale is useful only if it produces durable seller quality.</p></div>\n "},"4":{"title":"Commercial Performance","subtitle":"Seller value distribution, marketplace dependency and the commercial risk created by concentration.","html":"<div class=\"page-story-head\">\n   <div><span class=\"story-kicker\">COMMERCIAL PERFORMANCE</span><h2>Seller breadth is large, but economic value remains highly concentrated.</h2></div>\n   <p>The commercial question is not simply how many sellers exist. Management needs to know how much marketplace value depends on a small cohort and whether that dependency is resilient.</p>\n </div>\n <div class=\"story-metrics five\"><div><strong>0.792</strong><span>Seller Gini</span></div><div><strong>26.1%</strong><span>Top 1% share</span></div><div><strong>53.3%</strong><span>Top 5% share</span></div><div><strong>67.6%</strong><span>Top 10% share</span></div><div><strong>82.7%</strong><span>Top 20% share</span></div></div>\n <div class=\"analysis-lens-grid\">\n   <section class=\"analysis-lens\"><span>KEY FINDINGS</span><h3>A relatively small seller cohort carries most GMV proxy.</h3><p>The top 20% of positive-GMV sellers account for 82.7% of seller GMV proxy, and the distribution has a Gini coefficient of 0.792.</p></section>\n   <section class=\"analysis-lens\"><span>BUSINESS INTERPRETATION</span><h3>Seller count is not the same as economic diversification.</h3><p>A marketplace can have thousands of sellers but still depend economically on a narrow supply base. “Seller breadth” and “economic breadth” must be monitored separately.</p></section>\n   <section class=\"analysis-lens decision\"><span>RECOMMENDED ACTION</span><h3>Monitor dependency before prescribing diversification.</h3><p>Escalate when concentration rises materially and high-value categories simultaneously show fragile seller breadth or weak service quality.</p></section>\n </div>\n <div class=\"story-grid two\">\n   <section class=\"story-card visual-card\"><span class=\"card-label\">VALUE INEQUALITY</span><h3>Lorenz curve</h3><img loading=\"lazy\" src=\"https://raw.githubusercontent.com/susayold/marketplace-growth-seller-intelligence/main/reports/charts/05_seller_value_concentration/con_01_lorenz_curve.png\" alt=\"Seller GMV Lorenz curve\"><p class=\"card-foot\">A pronounced gap from the equality line reflects highly uneven seller contribution.</p></section>\n   <section class=\"story-card visual-card\"><span class=\"card-label\">PARETO DEPENDENCY</span><h3>Cumulative seller-value concentration</h3><img loading=\"lazy\" src=\"https://raw.githubusercontent.com/susayold/marketplace-growth-seller-intelligence/main/reports/charts/05_seller_value_concentration/con_02_pareto_cumulative_curve.png\" alt=\"Seller GMV Pareto curve\"><p class=\"card-foot\">Top-percentile monitoring turns concentration from a descriptive statistic into a commercial risk indicator.</p></section>\n </div>\n <div class=\"senior-assessment\">\n  <div class=\"assessment-title\"><span>DETAILED ANALYSIS</span><h3>Seller concentration and commercial resilience</h3></div>\n  <div class=\"assessment-copy\">\n    <p><b>The concentration metrics tell us that marketplace value is carried disproportionately by a relatively small seller cohort.</b> The top 1% of positive-GMV sellers generate about 26.1% of seller GMV proxy; the top 5% generate 53.3%; the top 10% generate 67.6%; and the top 20% generate 82.7%. A Gini of 0.792 confirms that contribution is highly uneven across the seller base.</p>\n    <p>The important management interpretation is not “concentration is bad”. The important interpretation is that <b>seller count and economic diversification are not the same thing</b>. A marketplace can report thousands of active sellers and still be commercially dependent on a relatively narrow group. If those sellers are reliable, productive and concentrated in attractive categories, that dependence may be efficient. The risk appears when concentration rises while category breadth, service quality or seller continuity weaken.</p>\n    <p>This is why This should not become a generic diversification initiative. It should be used as a resilience monitor. Management should know which high-value categories depend on very few sellers, whether those sellers are also driving service issues, and whether concentration is increasing month over month. That combination is more useful than a single Gini number viewed in isolation.</p>\n    <p>The Lorenz and Pareto views are especially useful because they convert an abstract statistic into a dependency story: management can see exactly how quickly cumulative GMV concentrates as we move through the seller distribution.</p>\n  </div>\n  <div class=\"assessment-decision\"><b>Management implication</b><p>Track top 1/5/10/20% seller share monthly and cross it with active-seller breadth by high-value category. Escalate when concentration increases at the same time that category breadth or service quality deteriorates. That creates a practical commercial-risk trigger rather than a blanket “diversify” rule.</p></div>\n</div><div class=\"management-box\"><div><span>RECOMMENDATION</span><h3>Pair concentration with category economics and service quality.</h3></div><p>Do not diversify indiscriminately. Concentration may be efficient if dominant sellers are productive and reliable. The risk rises when dependency is combined with weak category breadth, service deterioration, or supply instability.</p></div>\n "},"5":{"title":"Customer Experience & Operations","subtitle":"Delivery quality, review outcomes and where operations should investigate first.","html":"<div class=\"page-story-head\">\n   <div><span class=\"story-kicker\">CUSTOMER EXPERIENCE & OPERATIONS</span><h2>Late delivery is the strongest operational risk signal in the analysis and is large enough to merit management attention.</h2></div>\n   <p>The question is not whether late orders have statistically different reviews — they do. The more important question is whether the magnitude is large enough to prioritize operational investigation.</p>\n </div>\n <div class=\"cx-compare\">\n   <div class=\"cx-side good\"><span>ON TIME</span><strong>88,168</strong><small>reviewed delivered orders</small><div><b>4.29</b><em>Avg review</em></div><div><b>9.2%</b><em>Low-review rate</em></div></div>\n   <div class=\"cx-gap\"><span>OBSERVED GAP</span><strong>+44.8pp</strong><small>low-review risk</small><b>5.87× risk ratio</b></div>\n   <div class=\"cx-side bad\"><span>LATE</span><strong>7,662</strong><small>reviewed delivered orders</small><div><b>2.57</b><em>Avg review</em></div><div><b>54.0%</b><em>Low-review rate</em></div></div>\n </div>\n <div class=\"analysis-lens-grid\">\n   <section class=\"analysis-lens\"><span>KEY FINDINGS</span><h3>The review penalty is large, not merely statistically detectable.</h3><p>Late orders average 1.73 review points lower and have a 44.8 percentage-point higher low-review rate than on-time orders.</p></section>\n   <section class=\"analysis-lens\"><span>BUSINESS INTERPRETATION</span><h3>Delivery performance is a material customer-experience diagnostic.</h3><p>The effect is large enough to prioritize operational root-cause work even after acknowledging review selection and route/category confounding.</p></section>\n   <section class=\"analysis-lens decision\"><span>RECOMMENDED ACTION</span><h3>Investigate where operational pain is both large and material.</h3><p>Prioritize segments by <b>order volume × delay severity × review penalty</b>, then pilot targeted fixes rather than launching a blanket marketplace program.</p></section>\n </div>\n <div class=\"story-grid two\">\n   <section class=\"story-card visual-card\"><span class=\"card-label\">CUSTOMER RISK</span><h3>Low-review rate by delivery status</h3><img loading=\"lazy\" src=\"https://raw.githubusercontent.com/susayold/marketplace-growth-seller-intelligence/main/reports/charts/07_customer_experience/cx_03_low_review_rate_ci.png\" alt=\"Low review rate by lateness\"><p class=\"card-foot\">Observed risk difference = +44.8pp; observed risk ratio = 5.87×.</p></section>\n   <section class=\"story-card visual-card\"><span class=\"card-label\">SEVERITY</span><h3>Review outcomes weaken as delays become more severe</h3><img loading=\"lazy\" src=\"https://raw.githubusercontent.com/susayold/marketplace-growth-seller-intelligence/main/reports/charts/07_customer_experience/cx_04_delay_severity_vs_review.png\" alt=\"Delay severity versus review\"><p class=\"card-foot\">Adjusted diagnostic model: odds of low review increase by ~1.080× per additional delay day after observed controls.</p></section>\n </div>\n <div class=\"senior-assessment\">\n  <div class=\"assessment-title\"><span>DETAILED ANALYSIS</span><h3>Delivery performance and customer experience</h3></div>\n  <div class=\"assessment-copy\">\n    <p><b>The customer-experience gap between on-time and late orders is too large to treat as a minor service metric.</b> On-time reviewed delivered orders average 4.29 stars with a 9.2% low-review rate. Late orders average only 2.57 stars and a 54.0% low-review rate. The 44.8 percentage-point gap and 5.87× observed risk ratio make lateness a material operating issue, not just a statistically significant one.</p>\n    <p>For management, the important question is therefore not “Does lateness matter?” The data already says it is strongly associated with poor review outcomes. The practical question becomes <b>where does lateness hurt the most, and where can operations intervene first?</b> That requires ranking segments by three things together: order volume, delay severity and review penalty.</p>\n    <p>The adjusted model strengthens the diagnostic because the relationship remains after observed controls. The output should be framed operationally rather than as a causal uplift estimate. The goal is to identify high-priority investigation queues: categories, states, routes or other supported segments where the combination of high volume and high service penalty creates the largest business exposure.</p>\n    <p>This page also connects operations back to growth. Poor delivery experience can weaken review scores, which affects marketplace trust and may ultimately reduce repeat usage or seller attractiveness. So delivery quality should sit on the same executive scorecard as seller activation rather than being treated as an isolated logistics KPI.</p>\n  </div>\n  <div class=\"assessment-decision\"><b>Management implication</b><p>Create a weekly operational queue ranked by <b>volume × delay severity × review penalty</b>. Start with the highest-exposure segment, investigate the operational pathway, test a targeted fix, and track late-delivery rate plus low-review rate as the paired success metrics.</p></div>\n</div><div class=\"management-box\"><div><span>RECOMMENDATION</span><h3>Turn the CX finding into an operational queue.</h3></div><p>Rank categories, states or other supported segments by volume × lateness × review penalty. Test a fix in the highest-priority segment and monitor late-delivery rate, review outcomes, refunds/cost if available, and whether the effect survives segment-level robustness checks.</p></div>\n "},"6":{"title":"Root Cause & Diagnostic","subtitle":"A structured assessment of what is supported, rejected or still inconclusive.","html":"<div class=\"page-story-head\">\n   <div><span class=\"story-kicker\">ROOT-CAUSE ASSESSMENT</span><h2>Good diagnosis is as much about rejecting weak explanations as it is about finding plausible ones.</h2></div>\n   <p>The project evaluates six cases and twenty hypotheses. Each explanation is classified by evidence status, so management can distinguish confirmed measurement problems, supported business signals and hypotheses that still require testing.</p>\n </div>\n <div class=\"story-metrics three\"><div><strong>6</strong><span>Root-cause cases</span></div><div><strong>20</strong><span>Hypotheses assessed</span></div><div><strong>3 states</strong><span>Supported / rejected / inconclusive</span></div></div>\n <div class=\"analysis-lens-grid\">\n   <section class=\"analysis-lens\"><span>KEY FINDINGS</span><h3>There is no single “marketing problem.”</h3><p>The evidence points to multiple layers: a confirmed reporting-boundary issue, channel conversion differences, slow activation, seller concentration and a large delivery/CX association.</p></section>\n   <section class=\"analysis-lens\"><span>BUSINESS INTERPRETATION</span><h3>Management should separate measurement, funnel and operational mechanisms.</h3><p>Different problems require different owners. Treating all underperformance as a marketing-acquisition issue would send resources to the wrong part of the system.</p></section>\n   <section class=\"analysis-lens decision\"><span>RECOMMENDED ACTION</span><h3>Escalate only mechanisms that survive the diagnostic chain.</h3><p>Require evidence of materiality and actionability before turning a hypothesis into an operating initiative.</p></section>\n </div>\n <div class=\"root-case-grid\">\n   <article><span class=\"case-status supported\">Confirmed</span><b>RC1 · Reporting boundary</b><h3>Partial edge periods can mimic commercial collapse.</h3><p>Action: gate executive reporting on completeness.</p></article>\n   <article><span class=\"case-status associative\">Association</span><b>RC2 · Acquisition quality</b><h3>Origin is associated with conversion, but a durable channel winner is not established.</h3><p>Action: use a multidimensional channel scorecard.</p></article>\n   <article><span class=\"case-status supported\">Supported signal</span><b>RC3 · Activation</b><h3>Seller time-to-value is slow after conversion.</h3><p>Action: instrument 7/30/60-day onboarding checkpoints.</p></article>\n   <article><span class=\"case-status associative\">Risk signal</span><b>RC4 · Concentration</b><h3>Marketplace value depends heavily on a small seller cohort.</h3><p>Action: monitor top shares with category breadth.</p></article>\n   <article><span class=\"case-status associative\">Strong association</span><b>RC5 · Delivery & reviews</b><h3>Late delivery aligns with materially weaker review outcomes.</h3><p>Action: prioritize operational investigation by volume × severity × penalty.</p></article>\n   <article><span class=\"case-status inconclusive\">Diagnostic path</span><b>RC6 · Category underperformance</b><h3>A category decline can come from orders, AOV, seller breadth or productivity.</h3><p>Action: decompose before assigning a root cause.</p></article>\n </div>\n <div class=\"senior-assessment\">\n  <div class=\"assessment-title\"><span>DETAILED ANALYSIS</span><h3>Root-cause assessment and diagnostic priorities</h3></div>\n  <div class=\"assessment-copy\">\n    <p><b>Management problems often look similar at headline level but come from very different mechanisms.</b> A falling chart can be caused by incomplete data, weaker acquisition quality, slow activation, concentration, service deterioration or category mix. Page 6 forces those explanations to compete with evidence rather than allowing the analyst to choose the most convenient story.</p>\n    <p>RC1 is fundamentally a measurement-governance problem: partial edge periods can mimic a business collapse. RC2 is an acquisition-quality problem: origin is associated with conversion, but that alone does not identify a durable winner. RC3 is a post-conversion operating problem: seller time-to-value is slow. RC4 is a commercial resilience problem: value is concentrated. RC5 is an operational/CX problem: late delivery aligns with materially weaker reviews. RC6 is a diagnostic workflow: category declines need decomposition before management assigns a cause.</p>\n    <p>The biggest benefit for management is ownership clarity. If the issue is measurement, Data/BI owns the fix. If it is activation, Seller Operations owns the experiment. If it is concentration, Commercial Analytics owns monitoring. If it is late delivery, Operations/CX owns the investigation. That prevents every negative KPI from being pushed back to “marketing”.</p>\n    <p>This page should be used in monthly reviews as a hypothesis register: what changed, plausible explanations, supporting evidence, rejected explanations, and the next test.</p>\n  </div>\n  <div class=\"assessment-decision\"><b>Management implication</b><p>Do not launch an initiative from a headline movement alone. Require a short diagnostic chain: <b>trigger → hypothesis → evidence → business materiality → action owner → test</b>. This keeps the organization from solving the wrong problem.</p></div>\n</div><div class=\"management-box\"><div><span>BUSINESS IMPLICATION</span><h3>The analysis protects management from solving the wrong problem.</h3></div><p>RC1 should be fixed as measurement governance. RC2 and RC3 belong to growth / seller operations. RC4 belongs to commercial risk monitoring. RC5 belongs to operations / customer experience. RC6 requires category-specific diagnostic work before intervention.</p></div>\n "},"7":{"title":"Decision Center","subtitle":"Management actions, owner cadence, a 30–60–90 day execution plan and the KPI scorecard.","html":"<div class=\"page-story-head\">\n   <div><span class=\"story-kicker\">MANAGEMENT RECOMMENDED ACTION AGENDA</span><h2>Shift the operating model from lead acquisition to seller value creation.</h2></div>\n   <p>The final page converts the evidence into five governed decisions. Each action has a primary KPI, guardrail, owner, cadence and stop condition so that the report can drive management routines rather than remain a one-off analysis.</p>\n </div>\n <div class=\"story-metrics four\"><div><strong>5</strong><span>Governed decisions</span></div><div><strong>4</strong><span>P1 actions</span></div><div><strong>1</strong><span>P2 monitoring action</span></div><div><strong>PASS</strong><span>Analytical release</span></div></div>\n <div class=\"story-table-wrap decision-detail\"><table class=\"story-table\"><thead><tr><th>Priority</th><th>Decision</th><th>Action</th><th>Primary KPI</th><th>Guardrail</th><th>Owner / cadence</th></tr></thead><tbody>\n   <tr><td><span class=\"priority p1\">P1</span></td><td><b>D01</b> Measurement contract</td><td>Exclude or flag incomplete periods before trend reporting.</td><td>Period completeness</td><td>No valid period suppressed</td><td>Data / BI · Daily</td></tr>\n   <tr><td><span class=\"priority p1\">P1</span></td><td><b>D02</b> Acquisition scorecard</td><td>Govern on volume, conversion, seller value, activation and M3 retention.</td><td>Conversion + downstream value</td><td>M3 retention</td><td>Seller Acquisition · Weekly</td></tr>\n   <tr><td><span class=\"priority p1\">P1</span></td><td><b>D03</b> Onboarding checkpoints</td><td>Instrument 7/30/60D milestones and test interventions.</td><td>30/60D activation</td><td>Retention + downstream GMV</td><td>Seller Operations · Weekly</td></tr>\n   <tr><td><span class=\"priority p2\">P2</span></td><td><b>D04</b> Concentration monitoring</td><td>Track top seller shares and fragile category breadth.</td><td>Top 1/5/10/20% share</td><td>Active sellers / category</td><td>Commercial Analytics · Monthly</td></tr>\n   <tr><td><span class=\"priority p1\">P1</span></td><td><b>D05</b> Delivery investigation</td><td>Prioritize volume × delay severity × review penalty.</td><td>Late-delivery rate</td><td>Review / low-review rate</td><td>CX / Operations · Daily + weekly</td></tr>\n </tbody></table></div>\n <div class=\"report-subsection\"><div class=\"subsection-head\"><span>30–60–90 DAY ACTION PLAN</span><h3>Move from measurement to experimentation, then scale only what survives the guardrails.</h3></div>\n   <div class=\"action-plan-grid\">\n     <article><span>DAY 0–30</span><h3>Measure & instrument</h3><ul><li>Lock channel taxonomy and reduce unknown origin.</li><li>Publish weekly acquisition scorecard.</li><li>Track Day 7 / 30 / 60 onboarding milestones.</li><li>Enforce complete-period reporting gate.</li></ul><b>Success signal: reliable weekly scorecard and clean funnel observability.</b></article>\n     <article><span>DAY 31–60</span><h3>Diagnose & experiment</h3><ul><li>Test onboarding interventions in selected seller cohorts.</li><li>Investigate large actionable acquisition origins.</li><li>Segment slow activators by readiness/category.</li><li>Prioritize late-delivery segments by volume × severity × review penalty.</li></ul><b>Success signal: measurable activation/CX lift without guardrail breach.</b></article>\n     <article><span>DAY 61–90</span><h3>Scale, stop or redesign</h3><ul><li>Scale interventions only where effect persists.</li><li>Stop if activation improves while retention/value deteriorates.</li><li>Reject hypotheses with no measurable lift.</li><li>Refresh concentration and category-risk monitoring.</li></ul><b>Success signal: operating decisions tied to evidence, owner and stop condition.</b></article>\n   </div>\n </div>\n <div class=\"report-subsection\"><div class=\"subsection-head\"><span>MANAGEMENT KPI SCORECARD</span><h3>One scorecard across the seller-value funnel</h3></div>\n   <div class=\"story-table-wrap\"><table class=\"story-table kpi-scorecard\"><thead><tr><th>Funnel layer</th><th>KPI</th><th>Why it matters</th><th>Frequency</th><th>Owner</th><th>Role</th></tr></thead><tbody>\n     <tr><td>Acquisition</td><td>MQL volume</td><td>Top-of-funnel scale</td><td>Weekly</td><td>Growth</td><td><span class=\"metric-role primary\">Primary</span></td></tr>\n     <tr><td>Acquisition</td><td>Conversion rate</td><td>Lead-to-seller efficiency</td><td>Weekly</td><td>Growth</td><td><span class=\"metric-role primary\">Primary</span></td></tr>\n     <tr><td>Seller quality</td><td>GMV / matched seller</td><td>Downstream economic value</td><td>Weekly / Monthly</td><td>Growth / Commercial</td><td><span class=\"metric-role primary\">Primary</span></td></tr>\n     <tr><td>Activation</td><td>30D activation</td><td>Early seller time-to-value</td><td>Weekly</td><td>Seller Operations</td><td><span class=\"metric-role primary\">Primary</span></td></tr>\n     <tr><td>Activation</td><td>Median days to first sale</td><td>Activation speed</td><td>Weekly</td><td>Seller Operations</td><td><span class=\"metric-role monitor\">Monitor</span></td></tr>\n     <tr><td>Retention</td><td>M3 retention</td><td>Seller-quality guardrail</td><td>Monthly</td><td>Growth</td><td><span class=\"metric-role guardrail\">Guardrail</span></td></tr>\n     <tr><td>Data quality</td><td>Unknown-origin share</td><td>Attribution reliability</td><td>Weekly</td><td>Data / Marketing</td><td><span class=\"metric-role data\">Data quality</span></td></tr>\n     <tr><td>Operations</td><td>Late-delivery rate</td><td>CX operational risk</td><td>Daily / Weekly</td><td>Operations</td><td><span class=\"metric-role primary\">Primary</span></td></tr>\n   </tbody></table></div>\n </div>\n <div class=\"senior-assessment\">\n  <div class=\"assessment-title\"><span>DETAILED ANALYSIS</span><h3>Decision framework and execution priorities</h3></div>\n  <div class=\"assessment-copy\">\n    <p><b>The five decisions are intentionally linked.</b> D01 makes sure management is reading valid periods. D02 prevents the acquisition team from optimizing conversion in isolation. D03 converts slow activation into a measurable onboarding program. D04 makes seller concentration visible as a commercial resilience signal. D05 turns the delivery/CX relationship into an operational investigation queue.</p>\n    <p>What makes these decisions useful is the governance around them. Each one has a primary KPI, a guardrail, an owner and a review cadence. That means the analysis can be revisited every week or month and management can ask a very concrete question: <b>did the action improve the intended KPI without damaging the guardrail?</b></p>\n    <p>The 30–60–90 day plan is designed to sequence the work. The first 30 days are about observability and metric discipline. Days 31–60 are about targeted experiments and diagnosis. Days 61–90 are about scaling only the interventions that show a measurable improvement. That is a much stronger management process than rolling out a broad “growth initiative” without a stop condition.</p>\n    <p>The main executive message is therefore simple: the marketplace should be managed as a connected system. Marketing creates the seller pipeline; onboarding converts pipeline into productive supply; commercial monitoring protects resilience; operations protects customer experience; and analytics makes sure each decision is measured consistently.</p>\n  </div>\n  <div class=\"assessment-decision\"><b>Management implication</b><p>Use Page 7 as the standing review agenda. Every action should have one accountable owner, one primary KPI, one guardrail, a review date and an explicit scale/stop/redesign decision. That turns the project from a portfolio dashboard into a real decision-support framework.</p></div>\n</div><div class=\"management-box\"><div><span>FINAL RECOMMENDATION</span><h3>Measure correctly → identify the bottleneck → test the intervention → protect guardrails → monitor continuously.</h3></div><p>The report does not recommend a single “growth lever.” It recommends an operating framework linking acquisition, activation, commercial resilience and customer experience. That is the level at which the marketplace should be managed.</p></div>\n "}};
  let currentPage = 1;
  const imageFor = page => './assets/dashboard/page-' + page + '.png?v=final-20260923';

  function preload(page) {
    const img = new Image();
    img.src = imageFor(page);
  }

  function updateAnalysis(page) {
    const data = pageData[page];
    const content = document.getElementById('reportPageContent');
    const number = document.getElementById('analysisPageNumber');
    const prevLabel = document.getElementById('analysisPrevLabel');
    const nextLabel = document.getElementById('analysisNextLabel');
    if (content) {
      content.classList.add('switching');
      window.setTimeout(() => {
        content.innerHTML = data.html;
        content.classList.remove('switching');
      }, 90);
    }
    if (number) number.textContent = String(page).padStart(2,'0');
    const prev = page === 1 ? 7 : page - 1;
    const next = page === 7 ? 1 : page + 1;
    if (prevLabel) prevLabel.textContent = pageData[prev].title;
    if (nextLabel) nextLabel.textContent = pageData[next].title;
  }

  function showPage(pageNum, scrollToDashboard = false) {
    currentPage = Math.max(1, Math.min(7, pageNum));
    const data = pageData[currentPage];
    const image = document.getElementById('dashboardImage');
    const loading = document.getElementById('pdfLoading');
    const fullResLink = document.getElementById('dashboardFullRes');
    const fullResButton = document.getElementById('dashboardFullResButton');
    const pageImage = imageFor(currentPage);

    if (fullResLink) {
      fullResLink.href = pageImage;
      fullResLink.setAttribute('aria-label','Open dashboard page ' + currentPage + ' in full resolution');
    }
    if (fullResButton) fullResButton.href = pageImage;

    if (loading) {
      loading.textContent = 'Loading high-resolution Power BI page…';
      loading.classList.add('show');
    }

    if (image) {
      image.classList.add('is-loading');
      image.onload = () => {
        image.classList.remove('is-loading');
        loading?.classList.remove('show');
      };
      image.onerror = () => {
        image.classList.remove('is-loading');
        if (loading) {
          loading.innerHTML = 'Preview unavailable. <a href="./assets/final-market-dashboard.pdf?v=final-20260923" target="_blank" rel="noopener">Open the PDF →</a>';
          loading.classList.add('show');
        }
      };
      image.src = pageImage;
      image.alt = 'Power BI dashboard page ' + currentPage + ' — ' + data.title;
    }

    const title = document.getElementById('dashTitle');
    const subtitle = document.getElementById('dashSubtitle');
    const counter = document.getElementById('pageCurrent');
    if (title) title.textContent = data.title;
    if (subtitle) subtitle.textContent = data.subtitle;
    if (counter) counter.textContent = currentPage;

    document.querySelectorAll('#dashboardTabs button').forEach(btn => {
      btn.classList.toggle('active', Number(btn.dataset.page) === currentPage);
    });

    updateAnalysis(currentPage);
    preload(currentPage === 7 ? 1 : currentPage + 1);
    preload(currentPage === 1 ? 7 : currentPage - 1);

    const url = new URL(window.location.href);
    url.searchParams.set('page', currentPage);
    url.hash = 'dashboard';
    history.replaceState(null,'',url.pathname + url.search + url.hash);

    if (scrollToDashboard) {
      document.getElementById('dashboard')?.scrollIntoView({ behavior:'smooth', block:'start' });
    }
  }

  document.getElementById('prevPage')?.addEventListener('click', () => showPage(currentPage === 1 ? 7 : currentPage - 1));
  document.getElementById('nextPage')?.addEventListener('click', () => showPage(currentPage === 7 ? 1 : currentPage + 1));
  document.getElementById('analysisPrev')?.addEventListener('click', () => showPage(currentPage === 1 ? 7 : currentPage - 1, true));
  document.getElementById('analysisNext')?.addEventListener('click', () => showPage(currentPage === 7 ? 1 : currentPage + 1, true));
  document.querySelectorAll('#dashboardTabs button').forEach(btn => btn.addEventListener('click', () => showPage(Number(btn.dataset.page))));

  const heroImg = document.getElementById('heroDashboardImage');
  if (heroImg) {
    heroImg.onerror = () => {
      const screen = heroImg.closest('.laptop-screen');
      if (screen) screen.innerHTML = '<div class="hero-fallback">Power BI<br><strong>7-page Executive Report</strong></div>';
    };
  }

  const requested = Number(new URL(window.location.href).searchParams.get('page'));
  currentPage = requested >= 1 && requested <= 7 ? requested : 1;
  preload(currentPage);
  preload(currentPage === 7 ? 1 : currentPage + 1);
  showPage(currentPage);
})();
